232	    using seed_b_backend.Api.Application;
233	    using seed_b_backend.Api.Controllers.Dtos;
234	
235	    namespace seed_b_backend.Api.Controllers;
236	
237	    [ApiController]
238	    [Route("api/cart")]
239	    public class CartController(CartService cartService) : ControllerBase
240	    {
241	        [HttpPost("items")]
242	        public async Task<ActionResult<CartDto>> AddItem(
243	            [FromHeader(Name = "X-Cart-Id")] string? cartId,
244	            [FromBody] AddCartItemRequest request,
245	            CancellationToken ct = default)
246	        {
247	            var parsedCartId = Guid.TryParse(cartId, out var parsed) ? parsed : (Guid?)null;
248	
249	            var result = await cartService.AddItemAsync(parsedCartId, request.ProductId, request.SupplierId, request.Quantity, ct);
250	            if (result is null)
251	            {
252	                return NotFound();
253	            }
254	
255	            return Ok(MapToDto(result));
256	        }
