7	
8	@Component({
9	  selector: 'app-cart-view',
10	  templateUrl: './cart-view.html'
11	})
12	export class CartView {
13	  private cartApi = inject(CartApiService);
14	  private cartService = inject(CartService);
15	
16	  protected readonly cart = signal<Cart | null>(null);
17	  protected readonly loading = signal(true);
18	  protected readonly error = signal<string | null>(null);
19	  protected readonly busyKeys = signal<ReadonlySet<string>>(new Set());
20	
21	  constructor() {
22	    this.loading.set(true);
23	    this.cartApi.getCart(this.cartService.cartId()).subscribe({
24	      next: (cart) => {
25	        this.cart.set(cart);
26	        this.loading.set(false);
27	      },
28	      error: () => {
29	        this.loading.set(false);
30	        this.error.set('Warenkorb konnte nicht geladen werden.');
31	      }
32	    });
33	  }
34	
35	  protected lineKey(productId: string, supplierId: string): string {
36	    return `${productId}:${supplierId}`;
37	  }
38	
39	  protected isBusy(productId: string, supplierId: string): boolean {
40	    return this.busyKeys().has(this.lineKey(productId, supplierId));
41	  }
42	
43	  private setBusy(key: string, busy: boolean): void {
44	    const next = new Set(this.busyKeys());
45	    if (busy) {
46	      next.add(key);
47	    } else {
48	      next.delete(key);
49	    }
50	    this.busyKeys.set(next);
51	  }
52	
53	  protected updateQuantity(productId: string, supplierId: string, quantityRaw: string): void {
54	    const cartId = this.cartService.cartId();
55	    const quantity = Number(quantityRaw);
56	    if (!cartId || !Number.isInteger(quantity) || quantity < 1) {
57	      this.error.set('Bitte eine gültige Menge (mindestens 1) angeben.');
58	      return;
59	    }
60	
61	    const key = this.lineKey(productId, supplierId);
62	    this.setBusy(key, true);
63	    this.error.set(null);
64	
65	    this.cartApi.updateQuantity(cartId, productId, supplierId, quantity).subscribe({
66	      next: (cart) => {
67	        this.cart.set(cart);
68	        this.setBusy(key, false);
69	      },
70	      error: (err: HttpErrorResponse) => {
71	        this.setBusy(key, false);
72	        this.error.set(err.status === 409 ? 'Angebot nicht mehr verfügbar' : 'Menge konnte nicht geändert werden.');
73	      }
74	    });
75	  }
76	
77	  protected removeItem(productId: string, supplierId: string): void {
78	    const cartId = this.cartService.cartId();
79	    if (!cartId) {
80	      return;
81	    }
82	
83	    const key = this.lineKey(productId, supplierId);
84	    this.setBusy(key, true);
85	    this.error.set(null);
86	
87	    this.cartApi.removeItem(cartId, productId, supplierId).subscribe({
88	      next: (cart) => {
89	        this.cart.set(cart);
90	        this.setBusy(key, false);
91	      },
92	      error: () => {
93	        this.setBusy(key, false);
94	        this.error.set('Position konnte nicht entfernt werden.');
95	      }
96	    });
97	  }
98	}
